117	static struct conn *conn_for_role(struct hub *h, uint32_t role)
118	{
119		for (int i = 0; i < MAX_CONNS; i++)
120			if (h->conns[i].fd >= 0 && h->conns[i].role == role)
121				return &h->conns[i];
122		return NULL;
123	}
124	
125	static int role_alive(struct hub *h, uint32_t role, int64_t now)
126	{
127		struct conn *c = conn_for_role(h, role);
128	
129		return c != NULL && now - c->last_hb_ns < HB_STALE_NS;
130	}
131	
132	static void trigger_burst(struct hub *h, int64_t now)
133	{
134		struct event *ev = &h->ev;
135		struct conn *cam = conn_for_role(h, PSS_ROLE_CAM);
136		struct pss_msg m;
137		uint32_t evicted = 0;
138		int q;
139	
140		if (cam == NULL) {
141			pss_log("event %" PRIu64 ": camd not connected, no images", ev->id);
142			ev->flags |= PSS_EVF_NO_IMAGES;
143			return;
144		}
145		q = clip_enforce_quota(h->store.clips_dir_fd, h->quota_bytes, BURST_EST_BYTES, h->floor_pct, &evicted);
146		if (q != 0) {
147			pss_log("event %" PRIu64 ": %s, no images", ev->id, q > 0 ? "clips disabled" : "quota check failed");
148			ev->flags |= PSS_EVF_NO_IMAGES;
149			return;
150		}
151		pss_msg_init(&m, PSS_MSG_CAM_TRIGGER);
152		m.u.cam_trigger.event_id = ev->id;
153		m.u.cam_trigger.frames = h->burst_frames;
154		m.u.cam_trigger.interval_ms = h->burst_interval_ms;
155		if (ipc_send(cam->fd, &m) != 0) {
156			pss_log("event %" PRIu64 ": trigger to camd failed: %s", ev->id, strerror(errno));
157			ev->flags |= PSS_EVF_NO_IMAGES;
158			return;
159		}
160		ev->burst = BURST_PENDING;
161		ev->burst_deadline_ns = now + (int64_t)h->burst_frames * h->burst_interval_ms * PSS_NS_PER_MS + BURST_SLACK_NS;
162		h->cam_bursts++;
163	}
164	
165	/* pir: 1 if a PIR rise opened the event, 0 for a sound onset. */
166	static void open_event(struct hub *h, int64_t ts, int64_t now, int pir)
167	{
168		struct event *ev = &h->ev;
169	
170		memset(ev, 0, sizeof *ev);
171		ev->open = 1;
172		ev->id = h->store.next_event_id++;
173		ev->start_mono_ns = ts;
174		ev->start_wall_ns = pss_wall_ns() - (now - ts);
175		ev->last_activity_ns = now;
176		ev->pir_high = pir;
177		ev->pir_edges = pir ? 1 : 0;
178		if (!role_alive(h, PSS_ROLE_MIC, now))
179			ev->flags |= PSS_EVF_AUDIO_OFFLINE;
180		pss_log("event %" PRIu64 " opened (%s)", ev->id, pir ? "PIR rise" : "sound onset");
181	}
182	
183	/* Motion and sound coincided (dt_ns = onset time - rise time): the open
184	 * event becomes an ENTRY, durable at once, and only now is the camera
185	 * fired. Once per event. On a store failure sets h->fatal. */
186	static void confirm_entry(struct hub *h, int64_t dt_ns, int64_t now)
187	{
188		struct event *ev = &h->ev;
189		struct pss_rec_event_open o;
190	
191		if (ev->kind == PSS_EV_ENTRY)
192			return;
193		ev->kind = PSS_EV_ENTRY;
194		memset(&o, 0, sizeof o);
195		o.event_id = ev->id;
196		o.start_mono_ns = ev->start_mono_ns;
197		o.start_wall_ns = ev->start_wall_ns;
198		o.kind = PSS_EV_ENTRY;
199		o.flags = ev->flags;
200		if (store_event_open(&h->store, &o) != 0) {
201			pss_log("event %" PRIu64 ": store write failed; exiting so recovery runs", ev->id);
202			h->fatal = 1;
203			return;
204		}
205		pss_log("event %" PRIu64 ": ENTRY confirmed (motion+sound, sound %+.1fs from motion)",
206			ev->id, (double)dt_ns / PSS_NS_PER_S);
207		trigger_burst(h, now);
208	}
209	
210	/* Writes the event record and makes it durable. 0, or -1 on a store failure. */
211	static int close_event(struct hub *h, int64_t end_ns, uint32_t extra_flags)
212	{
213		struct event *ev = &h->ev;
214		struct pss_rec_event r;
215	
216		memset(&r, 0, sizeof r);
217		r.event_id = ev->id;
218		r.start_mono_ns = ev->start_mono_ns;
219		r.end_mono_ns = end_ns;
220		r.start_wall_ns = ev->start_wall_ns;
221		if (ev->kind == PSS_EV_ENTRY)
222			r.kind = PSS_EV_ENTRY;
223		else
224			r.kind = ev->pir_edges > 0 ? PSS_EV_MOTION_ONLY : PSS_EV_SOUND_ONLY;
225		r.flags = ev->flags | extra_flags;
226		r.pir_edges = ev->pir_edges;
227		r.n_images = ev->n_images;
228		if (store_event_close(&h->store, &r) != 0) {
229			pss_log("event %" PRIu64 ": store write failed; exiting so recovery runs", ev->id);
230			return -1;
231		}
232		pss_log("event %" PRIu64 " closed: %s dur=%.1fs edges=%" PRIu32 " images=%" PRIu32 "%s%s",
233			ev->id, r.kind == PSS_EV_ENTRY ? "ENTRY" : r.kind == PSS_EV_MOTION_ONLY ? "MOTION_ONLY" : "SOUND_ONLY", (double)(end_ns - ev->start_mono_ns) / PSS_NS_PER_S, r.pir_edges, r.n_images,
234			(r.flags & PSS_EVF_NO_IMAGES) ? " no-images" : "",
235			(r.flags & PSS_EVF_AUDIO_OFFLINE) ? " audio-offline" : "");
236		h->events_closed++;
237		ev->open = 0;
238		return 0;
239	}
240	
241	static void on_cam_done(struct hub *h, const struct pss_msg *m)
242	{
243		struct event *ev = &h->ev;
244		uint64_t id = m->u.cam_done.event_id;
245		uint32_t n = 0;
246	
247		if (!ev->open || id != ev->id || ev->burst != BURST_PENDING) {
248			pss_log("camd: late result for event %" PRIu64 ", discarding", id);
249			clip_discard(h->store.clips_dir_fd, id);
250			return;
251		}
252		ev->burst = BURST_DONE;
253		if (m->u.cam_done.status != 0 || m->u.cam_done.frames == 0) {
254			h->cam_failures++;
255			ev->flags |= PSS_EVF_NO_IMAGES;
256			pss_log("event %" PRIu64 ": burst failed (status %" PRId32 ", %" PRIu32 " frames)",
257				id, m->u.cam_done.status, m->u.cam_done.frames);
258			clip_discard(h->store.clips_dir_fd, id);
259			return;
260		}
261		if (clip_commit(h->store.clips_dir_fd, id, &n) != 0) {
262			h->cam_failures++;
263			ev->flags |= PSS_EVF_NO_IMAGES;
264			clip_discard(h->store.clips_dir_fd, id);
265			return;
266		}
267		ev->n_images = n;
268		pss_log("event %" PRIu64 ": committed %" PRIu32 " images to clips/%" PRIu64 ".dir", id, n, id);
269	}
270	
271	static void on_pir_edge(struct hub *h, const struct pss_msg *m, int64_t now)
272	{
273		struct event *ev = &h->ev;
274		int64_t dt = 0;
275	
276		h->pir_edges++;
277		if (m->u.pir.rising) {
278			int hit = fusion_rise(&h->fu, m->mono_ns, &dt);
279	
280			if (!ev->open) {
281				open_event(h, m->mono_ns, now, 1);
282			} else {
283				ev->pir_edges++;
284				ev->pir_high = 1;
285				ev->last_activity_ns = now;
286			}
287			if (hit)
288				confirm_entry(h, dt, now);
289		} else if (ev->open) {
290			ev->pir_high = 0;
291			ev->last_activity_ns = now;
292		}
293	}
294	
295	static void mic_bg_update(struct mic_bg *b, double flux, double lrms)
296	{
297		double a, d;
298	
299		b->n++;
300		a = 1.0 / (double)b->n;
301		if (a < MIC_ALPHA_MIN)
302			a = MIC_ALPHA_MIN;
303		d = flux - b->flux_mu;
304		b->flux_mu += a * d;
305		b->flux_var = (1.0 - a) * (b->flux_var + a * d * d);
306		d = lrms - b->lrms_mu;
307		b->lrms_mu += a * d;
308		b->lrms_var = (1.0 - a) * (b->lrms_var + a * d * d);
309	}
310	
311	static void on_mic_frame(struct hub *h, const struct pss_msg *m, int64_t now)
312	{
313		struct mic_bg *b = &h->mic;
314		struct event *ev = &h->ev;
315		double flux = m->u.mic.flux;
316		double rms = m->u.mic.rms;
317		double lrms, z, db;
318		int onset;
319	
320		h->mic_frames++;
321		if (!isfinite(flux) || !isfinite(rms) || rms < 0) {
322			pss_log("micd: non-finite frame ignored");
323			return;
324		}
325		lrms = log10(rms > MIC_RMS_FLOOR ? rms : MIC_RMS_FLOOR);
326		z = (flux - b->flux_mu) / sqrt(b->flux_var > MIC_FLUX_VAR_FLOOR ? b->flux_var : MIC_FLUX_VAR_FLOOR);
327		db = 20.0 * (lrms - b->lrms_mu);
328		onset = b->n >= h->mic_warmup && z >= h->onset_z && db >= h->onset_db;
329		if (b->n >= h->mic_warmup && !ev->open) {
330			if (z > b->z_max)
331				b->z_max = z;
332			if (db > b->db_max)
333				b->db_max = db;
334		}
335		if (onset) {
336			int64_t dt = 0;
337			int hit = fusion_onset(&h->fu, m->mono_ns, &dt);
338	
339			h->mic_onsets++;
340			pss_log("sound onset: flux z=%.1f, +%.1f dB over background", z, db);
341			if (!ev->open)
342				open_event(h, m->mono_ns, now, 0);
343			else
344				ev->last_activity_ns = now;
345			if (hit)
346				confirm_entry(h, dt, now);
347			return;
348		}
349		if (!ev->open)
350			mic_bg_update(b, flux, lrms);
351	}
352	
353	static void conn_drop(struct hub *h, int idx, const char *why)
354	{
355		struct conn *c = &h->conns[idx];
356	
357		if (epoll_ctl(h->epoll_fd, EPOLL_CTL_DEL, c->fd, NULL) != 0)
358			pss_log("epoll_ctl DEL: %s", strerror(errno));
359		if (close(c->fd) != 0)
360			pss_log("close conn: %s", strerror(errno));
361		pss_log("%s disconnected (%s)", pss_role_name(c->role), why);
362		if (c->role == PSS_ROLE_CAM && h->ev.open && h->ev.burst == BURST_PENDING) {
363			h->ev.burst = BURST_DONE;
364			h->ev.flags |= PSS_EVF_NO_IMAGES;
365			h->cam_failures++;
366		}
367		if (c->role == PSS_ROLE_PIR) {
368			h->ev.pir_high = 0; /* don't hold an event open on a dead sensor */
369			fusion_forget(&h->fu, 1, 0);
370		}
371		if (c->role == PSS_ROLE_MIC) {
372			memset(&h->mic, 0, sizeof h->mic); /* relearn: the device or room may differ */
373			fusion_forget(&h->fu, 0, 1);
374		}
375		c->fd = -1;
376		c->role = PSS_ROLE_NONE;
377	}
378	
379	static void handle_msg(struct hub *h, int idx, const struct pss_msg *m, int64_t now)
380	{
381		struct conn *c = &h->conns[idx];
382	
383		if (c->role == PSS_ROLE_NONE && m->type != PSS_MSG_HELLO) {
384			conn_drop(h, idx, "message before HELLO");
385			return;
386		}
387		switch (m->type) {
388		case PSS_MSG_HELLO:
389			if (m->u.hello.role < PSS_ROLE_PIR || m->u.hello.role > PSS_ROLE_MIC) {
390				conn_drop(h, idx, "bad role");
391				return;
392			}
393			c->role = m->u.hello.role;
394			c->last_hb_ns = now;
395			pss_log("%s connected (pid %" PRIu32 ")", pss_role_name(c->role), m->u.hello.pid);
396			break;
397		case PSS_MSG_HEARTBEAT:
398			c->last_hb_ns = now;
399			break;
400		case PSS_MSG_PIR_EDGE:
401			on_pir_edge(h, m, now);
402			break;
403		case PSS_MSG_CAM_DONE:
404			on_cam_done(h, m);
405			break;
406		case PSS_MSG_MIC_FRAME:
407			on_mic_frame(h, m, now);
408			break;
409		case PSS_MSG_BUTTON: /* arm state machine not yet implemented */
410			pss_log("arm button press #%" PRIu32, m->u.button.presses);
411			break;
412		default:
413			pss_log("%s: unknown message type %u", pss_role_name(c->role), m->type);
414			break;
415		}
416	}
417	
418	static void conn_readable(struct hub *h, int idx, int64_t now)
419	{
420		struct pss_msg m;
421		int r;
422	
423		while (h->conns[idx].fd >= 0) {
424			r = ipc_recv(h->conns[idx].fd, &m);
425			if (r == 1) {
426				handle_msg(h, idx, &m, now);
427				continue;
428			}
429			if (r == 0)
430				conn_drop(h, idx, "EOF");
431			else if (errno != EAGAIN)
432				conn_drop(h, idx, strerror(errno));
433			return;
434		}
435	}
436	
437	static void accept_all(struct hub *h, int64_t now)
438	{
439		for (;;) {
440			struct epoll_event ee = { .events = EPOLLIN };
441			int fd = accept4(h->listen_fd, NULL, NULL, SOCK_CLOEXEC | SOCK_NONBLOCK);
442			int idx = -1;
443	
444			if (fd < 0) {
445				if (errno != EAGAIN && errno != EINTR)
446					pss_log("accept4: %s", strerror(errno));
447				return;
448			}
449			for (int i = 0; i < MAX_CONNS; i++) {
450				if (h->conns[i].fd < 0) {
451					idx = i;
452					break;
453				}
454			}
455			if (idx < 0) {
456				pss_log("too many connections, refusing one");
457				close(fd);
458				continue;
459			}
460			ee.data.u32 = (uint32_t)idx;
461			if (epoll_ctl(h->epoll_fd, EPOLL_CTL_ADD, fd, &ee) != 0) {
462				pss_log("epoll_ctl ADD: %s", strerror(errno));
463				close(fd);
464				continue;
465			}
466			h->conns[idx] = (struct conn){ .fd = fd, .role = PSS_ROLE_NONE, .last_hb_ns = now };
467		}
468	}
