#ifndef PSS_STORE_EVLOG_H
#define PSS_STORE_EVLOG_H

/*
 * Mechanism D, event and stats logs (DESIGN.md Section 5): two append-only
 * logs of segment files, events/seg-NNNNNN.pel and stats/seg-NNNNNN.pel,
 * each record framed as
 *     [len u32][type u16][ver u16][payload: len bytes][crc32 u32]
 * with the CRC over header + payload. Native little-endian (Pi 5 and the lab
 * machines are both LE). Recovery at open truncates the newest segment of
 * each log at the first record with a bad length or CRC, and closes any
 * ENTRY that was opened but never closed as interrupted (power lost).
 */

#include <stdint.h>

#define PSS_SEG_MAX (4u * 1024 * 1024)
#define PSS_REC_MAX_PAYLOAD 4096u
#define PSS_REC_HDR 8u
#define PSS_REC_TRAILER 4u
#define PSS_REC_VER 1
#define PSS_STATS_RETAIN_S (7 * 24 * 3600)	/* whole stats segments older than this are deleted */
#define PSS_STATS_ROLL_NS (24 * 3600 * INT64_C(1000000000)) /* so a segment can age out */

enum pss_log_which {
	PSS_LOG_EVENTS = 0,
	PSS_LOG_STATS = 1,
};

enum pss_rec_type {
	PSS_REC_BOOT = 1,	/* events log */
	PSS_REC_EVENT = 2,	/* events log: a complete event, or the close of an EVENT_OPEN */
	PSS_REC_STATS = 3,	/* stats log only */
	PSS_REC_EVENT_OPEN = 4,	/* events log: ENTRY confirmed, made durable at once */
};

enum pss_event_kind {
	PSS_EV_MOTION_ONLY = 1,
	PSS_EV_ENTRY = 2,	/* needs fusion (M4) */
	PSS_EV_SOUND_ONLY = 3,	/* needs fusion (M4) */
};

enum pss_event_flag {
	PSS_EVF_NO_IMAGES = 1u << 0,
	PSS_EVF_AUDIO_OFFLINE = 1u << 1,
	PSS_EVF_CLOSED_AT_SHUTDOWN = 1u << 2,
	PSS_EVF_INTERRUPTED = 1u << 3,	/* opened, power lost before close; end unknown */
};

/* Payload structs have no implicit padding; read them back with memcpy (payloads are unaligned). */
struct pss_rec_boot {
	uint64_t boot_no;
	int64_t mono_ns;
	int64_t wall_ns;
};

/* Images, if any, live in clips/<event_id>.dir. */
struct pss_rec_event {
	uint64_t event_id;
	int64_t start_mono_ns;
	int64_t end_mono_ns;
	int64_t start_wall_ns;
	uint32_t kind;
	uint32_t flags;
	uint32_t pir_edges;
	uint32_t n_images;
};

struct pss_rec_event_open {
	uint64_t event_id;
	int64_t start_mono_ns;
	int64_t start_wall_ns;
	uint32_t kind;
	uint32_t flags;
};

struct pss_rec_stats {
	int64_t mono_ns;
	int64_t wall_ns;
	uint64_t pir_edges;
	uint64_t mic_frames;
	uint64_t cam_bursts;
	uint64_t cam_failures;
	uint32_t sensors_ok;	/* bit (1 << role) set if that daemon heartbeated recently */
	uint32_t pad;
};

struct store_recovery {
	uint32_t seg_no;		/* events log */
	uint64_t valid_records;
	uint64_t truncated_bytes;
	uint32_t stats_seg_no;		/* stats log, before the fresh segment started at open */
	uint64_t stats_valid_records;
	uint64_t stats_truncated_bytes;
	uint32_t stats_pruned;
	uint32_t interrupted;		/* dangling ENTRY opens closed as interrupted */
	uint32_t tmp_removed;
};

/* One append-only log: a directory of segments, the newest open for append. */
struct seglog {
	const char *name;	/* "events" or "stats" */
	int dir_fd;
	int seg_fd;
	uint32_t seg_no;
	uint64_t seg_size;
	int64_t seg_started_ns;	/* CLOCK_MONOTONIC when this process opened or created it */
	uint8_t buf[PSS_REC_HDR + PSS_REC_MAX_PAYLOAD + PSS_REC_TRAILER];
};

struct pss_store {
	int root_fd;
	int clips_dir_fd;
	struct seglog events;
	struct seglog stats;
	int64_t stats_roll_ns;	/* PSS_STATS_ROLL_NS; tests may shorten it */
	uint64_t next_event_id;	/* above every id in the log and in clips/ */
	uint64_t boot_no;	/* highest boot_no in the log */
	struct store_recovery recovered;
};

/* Creates root/{events,stats,clips} if needed, runs recovery, opens both logs
 * for append. Returns 0 or -1 (logged; *s is closed). */
int store_open(struct pss_store *s, const char *root);
/* Appends one record (not yet durable) to the given log. STATS records go to
 * the stats log and every other type to the events log. 0 or -1. */
int store_append(struct pss_store *s, enum pss_log_which which, uint16_t type, const void *payload, uint32_t len);
/* fdatasync the given log's current segment. 0 or -1. */
int store_sync(struct pss_store *s, enum pss_log_which which);
/* ENTRY confirmed: append EVENT_OPEN and make it durable. 0 or -1. */
int store_event_open(struct pss_store *s, const struct pss_rec_event_open *o);
/* Event ended (or a one-shot event): append EVENT and make it durable. 0 or -1. */
int store_event_close(struct pss_store *s, const struct pss_rec_event *e);
void store_close(struct pss_store *s);

/* Visitor for store_scan; nonzero return stops the scan and is returned. */
typedef int (*store_visit_fn)(uint32_t seg_no, uint16_t type, uint16_t ver,
			      const void *payload, uint32_t len, void *arg);

/* Read-only walk over every valid record of one log, oldest first. */
int store_scan(const char *root, enum pss_log_which which, store_visit_fn fn, void *arg);

/* Length of the valid record prefix of buf; *n_records gets the count (may be NULL). */
uint64_t store_valid_prefix(const uint8_t *buf, uint64_t size, uint64_t *n_records);

#endif

content.content:
1	/*
2	 * hub: the single writer (DESIGN.md Section 2). Accepts sensor daemons on
3	 * $PSS_RUN_DIR/hub.sock, turns PIR edges into events, asks camd for an image
4	 * burst per event, and commits everything through the store (mechanism D).
5	 *
6	 * Fusion (DESIGN.md Section 4, src/analysis/fusion.c): a PIR rise opens a
7	 * MOTION_ONLY event and a sound onset (below) opens a SOUND_ONLY event, but
8	 * neither takes images. Only when a rise and an onset fall within +-T_co of
9	 * each other (either order) does the event become an ENTRY: it is made
10	 * durable at once and camd is asked for a burst, once per event.
11	 *
12	 * M3 sound trigger (stand-in for DESIGN.md Section 4's detectors, M4): an
13	 * EWMA background model of spectral flux and log RMS, learned only while no
14	 * event is open. A frame is an onset when its flux z-score and its loudness
15	 * above the room background both pass thresholds, so steady noise (fans,
16	 * AC) never triggers: its flux stays near its own mean and its level is the
17	 * background. Thresholds are placeholders until tuned on Pi recordings.
18	 *
19	 * Exit codes: 0 on SIGTERM/SIGINT, 1 on error (including any store write
20	 * failure, so the supervisor restarts us and recovery runs), 2 on usage.
21	 */
22	#include "analysis/fusion.h"
23	#include "common/ipc.h"
24	#include "common/log.h"
25	#include "common/time.h"
26	#include "common/util.h"
27	#include "store/clip.h"
28	#include "store/evlog.h"
29	
30	#include <errno.h>
31	#include <getopt.h>
32	#include <inttypes.h>
33	#include <math.h>
34	#include <signal.h>
35	#include <stdio.h>
36	#include <string.h>
37	#include <sys/epoll.h>
38	#include <sys/signalfd.h>
39	#include <sys/socket.h>
40	#include <sys/stat.h>
41	#include <unistd.h>
42	
43	#define EXIT_USAGE 2
44	#define MAX_CONNS 8
45	#define HB_FIRST_NS (5 * PSS_NS_PER_S)
46	#define HB_EVERY_NS (60 * PSS_NS_PER_S)
47	#define HB_STALE_NS (15 * PSS_NS_PER_S)
48	#define BURST_SLACK_NS (20 * PSS_NS_PER_S)
49	#define BURST_EST_BYTES (9ull * 1024 * 1024)	/* upper end of DESIGN.md Section 5's 6-9 MB */
50	#define MIC_ALPHA_MIN (1.0 / 3000)	/* 60 s time constant at 50 frames/s */
51	#define MIC_FLUX_VAR_FLOOR (0.05 * 0.05)
52	#define MIC_LRMS_VAR_FLOOR (0.01 * 0.01)
53	#define MIC_RMS_FLOOR 1e-6		/* keeps log10 finite on digital silence */
54	
55	enum { TAG_LISTEN = MAX_CONNS, TAG_SIG, TAG_TICK };
56	
57	struct conn {
58		int fd;
59		uint32_t role;		/* PSS_ROLE_NONE until HELLO */
60		int64_t last_hb_ns;
61	};
62	
63	enum burst_state { BURST_NONE, BURST_PENDING, BURST_DONE };
64	
65	struct event {
66		int open;
67		uint64_t id;
68		uint32_t kind;		/* PSS_EV_ENTRY once confirmed; else set at close */
69		int64_t start_mono_ns;
70		int64_t start_wall_ns;
71		int64_t last_activity_ns;
72		int pir_high;
73		uint32_t pir_edges;
74		uint32_t flags;
75		uint32_t n_images;
76		enum burst_state burst;
77		int64_t burst_deadline_ns;
78	};
79	
80	/* EWMA mean/variance of flux and log10(rms), learned outside events. */
81	struct mic_bg {
82		uint64_t n;
83		double flux_mu, flux_var;
84		double lrms_mu, lrms_var;
85		double z_max, db_max;	/* largest scores since the last heartbeat, for tuning */
86	};
87	
88	struct hub {
89		struct pss_store store;
90		int store_open;
91		int listen_fd, epoll_fd, sig_fd, tick_fd;
92		struct conn conns[MAX_CONNS];
93		struct event ev;
94		struct mic_bg mic;
95		struct fusion fu;
96		int fatal;		/* a store write failed inside a handler: exit so recovery runs */
97		int64_t start_ns, next_hb_ns;
98		uint64_t pir_edges, mic_frames, cam_bursts, cam_failures, events_closed, mic_onsets;
99		/* config */
100		int64_t quiet_ns, t_co_ns;
101		uint32_t burst_frames, burst_interval_ms, floor_pct;
102		uint64_t quota_bytes;
103		double onset_z, onset_db;
104		uint32_t mic_warmup;
105		char sock_path[108];
106	};
107	
108	static struct hub hub;
109	
110	static void usage(void)
111	{
112		fprintf(stderr, "usage: hub [--quiet-ms=30000] [--burst-frames=20] [--burst-interval-ms=500]\n"
113				"           [--quota-mb=2048] [--floor-pct=5]\n"
114				"           [--onset-z=6] [--onset-db=10] [--warmup-frames=250] [--t-co-ms=5000]\n");
115	}
116	
117	static struct conn *conn_for_role(struct hub *h, uint32_t role)
118	{
119		for (int i = 0; i < MAX_CONNS; i++)
120			if (h->conns[i].fd >= 0 && h->conns[i].role == role)
121				return &h->conns[i];
122		return NULL;
123	}
124	
125	static int role_alive(struct hub *h, uint32_t role, int64_t now)
126	{
127		struct conn *c = conn_for_role(h, role);
128	
129		return c != NULL && now - c->last_hb_ns < HB_STALE_NS;
130	}
131	
132	static void trigger_burst(struct hub *h, int64_t now)
133	{
134		struct event *ev = &h->ev;
135		struct conn *cam = conn_for_role(h, PSS_ROLE_CAM);
136		struct pss_msg m;
137		uint32_t evicted = 0;
138		int q;
139	
140		if (cam == NULL) {
141			pss_log("event %" PRIu64 ": camd not connected, no images", ev->id);
142			ev->flags |= PSS_EVF_NO_IMAGES;
143			return;
144		}
145		q = clip_enforce_quota(h->store.clips_dir_fd, h->quota_bytes, BURST_EST_BYTES, h->floor_pct, &evicted);
146		if (q != 0) {
147			pss_log("event %" PRIu64 ": %s, no images", ev->id, q > 0 ? "clips disabled" : "quota check failed");
148			ev->flags |= PSS_EVF_NO_IMAGES;
149			return;
150		}
151		pss_msg_init(&m, PSS_MSG_CAM_TRIGGER);
152		m.u.cam_trigger.event_id = ev->id;
153		m.u.cam_trigger.frames = h->burst_frames;
154		m.u.cam_trigger.interval_ms = h->burst_interval_ms;
155		if (ipc_send(cam->fd, &m) != 0) {
156			pss_log("event %" PRIu64 ": trigger to camd failed: %s", ev->id, strerror(errno));
157			ev->flags |= PSS_EVF_NO_IMAGES;
158			return;
159		}
160		ev->burst = BURST_PENDING;
161		ev->burst_deadline_ns = now + (int64_t)h->burst_frames * h->burst_interval_ms * PSS_NS_PER_MS + BURST_SLACK_NS;
162		h->cam_bursts++;
163	}
164	
165	/* pir: 1 if a PIR rise opened the event, 0 for a sound onset. */
166	static void open_event(struct hub *h, int64_t ts, int64_t now, int pir)
167	{
168		struct event *ev = &h->ev;
169	
170		memset(ev, 0, sizeof *ev);
171		ev->open = 1;
172		ev->id = h->store.next_event_id++;
173		ev->start_mono_ns = ts;
174		ev->start_wall_ns = pss_wall_ns() - (now - ts);
175		ev->last_activity_ns = now;
176		ev->pir_high = pir;
177		ev->pir_edges = pir ? 1 : 0;
178		if (!role_alive(h, PSS_ROLE_MIC, now))
179			ev->flags |= PSS_EVF_AUDIO_OFFLINE;
180		pss_log("event %" PRIu64 " opened (%s)", ev->id, pir ? "PIR rise" : "sound onset");
181	}
182	
183	/* Motion and sound coincided (dt_ns = onset time - rise time): the open
184	 * event becomes an ENTRY, durable at once, and only now is the camera
185	 * fired. Once per event. On a store failure sets h->fatal. */
186	static void confirm_entry(struct hub *h, int64_t dt_ns, int64_t now)
187	{
188		struct event *ev = &h->ev;
189		struct pss_rec_event_open o;
190	
191		if (ev->kind == PSS_EV_ENTRY)
192			return;
193		ev->kind = PSS_EV_ENTRY;
194		memset(&o, 0, sizeof o);
195		o.event_id = ev->id;
196		o.start_mono_ns = ev->start_mono_ns;
197		o.start_wall_ns = ev->start_wall_ns;
198		o.kind = PSS_EV_ENTRY;
199		o.flags = ev->flags;
200		if (store_event_open(&h->store, &o) != 0) {
201			pss_log("event %" PRIu64 ": store write failed; exiting so recovery runs", ev->id);
202			h->fatal = 1;
203			return;
204		}
205		pss_log("event %" PRIu64 ": ENTRY confirmed (motion+sound, sound %+.1fs from motion)",
206			ev->id, (double)dt_ns / PSS_NS_PER_S);
207		trigger_burst(h, now);
208	}
209	
210	/* Writes the event record and makes it durable. 0, or -1 on a store failure. */
211	static int close_event(struct hub *h, int64_t end_ns, uint32_t extra_flags)
212	{
213		struct event *ev = &h->ev;
214		struct pss_rec_event r;
215	
216		memset(&r, 0, sizeof r);
217		r.event_id = ev->id;
218		r.start_mono_ns = ev->start_mono_ns;
219		r.end_mono_ns = end_ns;
220		r.start_wall_ns = ev->start_wall_ns;
221		if (ev->kind == PSS_EV_ENTRY)
222			r.kind = PSS_EV_ENTRY;
223		else
224			r.kind = ev->pir_edges > 0 ? PSS_EV_MOTION_ONLY : PSS_EV_SOUND_ONLY;
225		r.flags = ev->flags | extra_flags;
226		r.pir_edges = ev->pir_edges;
227		r.n_images = ev->n_images;
228		if (store_event_close(&h->store, &r) != 0) {
229			pss_log("event %" PRIu64 ": store write failed; exiting so recovery runs", ev->id);
230			return -1;
231		}
232		pss_log("event %" PRIu64 " closed: %s dur=%.1fs edges=%" PRIu32 " images=%" PRIu32 "%s%s",
233			ev->id, r.kind == PSS_EV_ENTRY ? "ENTRY" : r.kind == PSS_EV_MOTION_ONLY ? "MOTION_ONLY" : "SOUND_ONLY", (double)(end_ns - ev->start_mono_ns) / PSS_NS_PER_S, r.pir_edges, r.n_images,
234			(r.flags & PSS_EVF_NO_IMAGES) ? " no-images" : "",
235			(r.flags & PSS_EVF_AUDIO_OFFLINE) ? " audio-offline" : "");
236		h->events_closed++;
237		ev->open = 0;
238		return 0;
239	}
240	
241	static void on_cam_done(struct hub *h, const struct pss_msg *m)
242	{
243		struct event *ev = &h->ev;
244		uint64_t id = m->u.cam_done.event_id;
245		uint32_t n = 0;
246	
247		if (!ev->open || id != ev->id || ev->burst != BURST_PENDING) {
248			pss_log("camd: late result for event %" PRIu64 ", discarding", id);
249			clip_discard(h->store.clips_dir_fd, id);
250			return;
251		}
252		ev->burst = BURST_DONE;
253		if (m->u.cam_done.status != 0 || m->u.cam_done.frames == 0) {
254			h->cam_failures++;
255			ev->flags |= PSS_EVF_NO_IMAGES;
256			pss_log("event %" PRIu64 ": burst failed (status %" PRId32 ", %" PRIu32 " frames)",
257				id, m->u.cam_done.status, m->u.cam_done.frames);
258			clip_discard(h->store.clips_dir_fd, id);
259			return;
260		}
261		if (clip_commit(h->store.clips_dir_fd, id, &n) != 0) {
262			h->cam_failures++;
263			ev->flags |= PSS_EVF_NO_IMAGES;
264			clip_discard(h->store.clips_dir_fd, id);
265			return;
266		}
267		ev->n_images = n;
268		pss_log("event %" PRIu64 ": committed %" PRIu32 " images to clips/%" PRIu64 ".dir", id, n, id);
269	}
270	
271	static void on_pir_edge(struct hub *h, const struct pss_msg *m, int64_t now)
272	{
273		struct event *ev = &h->ev;
274		int64_t dt = 0;
275	
276		h->pir_edges++;
277		if (m->u.pir.rising) {
278			int hit = fusion_rise(&h->fu, m->mono_ns, &dt);
279	
280			if (!ev->open) {
281				open_event(h, m->mono_ns, now, 1);
282			} else {
283				ev->pir_edges++;
284				ev->pir_high = 1;
285				ev->last_activity_ns = now;
286			}
287			if (hit)
288				confirm_entry(h, dt, now);
289		} else if (ev->open) {
290			ev->pir_high = 0;
291			ev->last_activity_ns = now;
292		}
293	}
294	
295	static void mic_bg_update(struct mic_bg *b, double flux, double lrms)
296	{
297		double a, d;
298	
299		b->n++;
300		a = 1.0 / (double)b->n;
301		if (a < MIC_ALPHA_MIN)
302			a = MIC_ALPHA_MIN;
303		d = flux - b->flux_mu;
304		b->flux_mu += a * d;
305		b->flux_var = (1.0 - a) * (b->flux_var + a * d * d);
306		d = lrms - b->lrms_mu;
307		b->lrms_mu += a * d;
308		b->lrms_var = (1.0 - a) * (b->lrms_var + a * d * d);
309	}
310	
311	static void on_mic_frame(struct hub *h, const struct pss_msg *m, int64_t now)
312	{
313		struct mic_bg *b = &h->mic;
314		struct event *ev = &h->ev;
315		double flux = m->u.mic.flux;
316		double rms = m->u.mic.rms;
317		double lrms, z, db;
318		int onset;
319	
320		h->mic_frames++;
321		if (!isfinite(flux) || !isfinite(rms) || rms < 0) {
322			pss_log("micd: non-finite frame ignored");
323			return;
324		}
325		lrms = log10(rms > MIC_RMS_FLOOR ? rms : MIC_RMS_FLOOR);
326		z = (flux - b->flux_mu) / sqrt(b->flux_var > MIC_FLUX_VAR_FLOOR ? b->flux_var : MIC_FLUX_VAR_FLOOR);
327		db = 20.0 * (lrms - b->lrms_mu);
328		onset = b->n >= h->mic_warmup && z >= h->onset_z && db >= h->onset_db;
329		if (b->n >= h->mic_warmup && !ev->open) {
330			if (z > b->z_max)
331				b->z_max = z;
332			if (db > b->db_max)
333				b->db_max = db;
334		}
335		if (onset) {
336			int64_t dt = 0;
337			int hit = fusion_onset(&h->fu, m->mono_ns, &dt);
338	
339			h->mic_onsets++;
340			pss_log("sound onset: flux z=%.1f, +%.1f dB over background", z, db);
341			if (!ev->open)
342				open_event(h, m->mono_ns, now, 0);
343			else
344				ev->last_activity_ns = now;
345			if (hit)
346				confirm_entry(h, dt, now);
347			return;
348		}
349		if (!ev->open)
350			mic_bg_update(b, flux, lrms);
351	}
352	
353	static void conn_drop(struct hub *h, int idx, const char *why)
354	{
355		struct conn *c = &h->conns[idx];
356	
357		if (epoll_ctl(h->epoll_fd, EPOLL_CTL_DEL, c->fd, NULL) != 0)
358			pss_log("epoll_ctl DEL: %s", strerror(errno));
359		if (close(c->fd) != 0)
360			pss_log("close conn: %s", strerror(errno));
361		pss_log("%s disconnected (%s)", pss_role_name(c->role), why);
362		if (c->role == PSS_ROLE_CAM && h->ev.open && h->ev.burst == BURST_PENDING) {
363			h->ev.burst = BURST_DONE;
364			h->ev.flags |= PSS_EVF_NO_IMAGES;
365			h->cam_failures++;
366		}
367		if (c->role == PSS_ROLE_PIR) {
368			h->ev.pir_high = 0; /* don't hold an event open on a dead sensor */
369			fusion_forget(&h->fu, 1, 0);
370		}
371		if (c->role == PSS_ROLE_MIC) {
372			memset(&h->mic, 0, sizeof h->mic); /* relearn: the device or room may differ */
373			fusion_forget(&h->fu, 0, 1);
374		}
375		c->fd = -1;
376		c->role = PSS_ROLE_NONE;
377	}
378	
379	static void handle_msg(struct hub *h, int idx, const struct pss_msg *m, int64_t now)
380	{
381		struct conn *c = &h->conns[idx];
382	
383		if (c->role == PSS_ROLE_NONE && m->type != PSS_MSG_HELLO) {
384			conn_drop(h, idx, "message before HELLO");
385			return;
386		}
387		switch (m->type) {
388		case PSS_MSG_HELLO:
389			if (m->u.hello.role < PSS_ROLE_PIR || m->u.hello.role > PSS_ROLE_MIC) {
390				conn_drop(h, idx, "bad role");
391				return;
392			}
393			c->role = m->u.hello.role;
394			c->last_hb_ns = now;
395			pss_log("%s connected (pid %" PRIu32 ")", pss_role_name(c->role), m->u.hello.pid);
396			break;
397		case PSS_MSG_HEARTBEAT:
398			c->last_hb_ns = now;
399			break;
400		case PSS_MSG_PIR_EDGE:
401			on_pir_edge(h, m, now);
402			break;
403		case PSS_MSG_CAM_DONE:
404			on_cam_done(h, m);
405			break;
406		case PSS_MSG_MIC_FRAME:
407			on_mic_frame(h, m, now);
408			break;
409		case PSS_MSG_BUTTON: /* arm state machine not yet implemented */
410			pss_log("arm button press #%" PRIu32, m->u.button.presses);
411			break;
412		default:
413			pss_log("%s: unknown message type %u", pss_role_name(c->role), m->type);
414			break;
415		}
416	}
417	
418	static void conn_readable(struct hub *h, int idx, int64_t now)
419	{
420		struct pss_msg m;
421		int r;
422	
423		while (h->conns[idx].fd >= 0) {
424			r = ipc_recv(h->conns[idx].fd, &m);
425			if (r == 1) {
426				handle_msg(h, idx, &m, now);
427				continue;
428			}
429			if (r == 0)
430				conn_drop(h, idx, "EOF");
431			else if (errno != EAGAIN)
432				conn_drop(h, idx, strerror(errno));
433			return;
434		}
435	}
436	
437	static void accept_all(struct hub *h, int64_t now)
438	{
439		for (;;) {
440			struct epoll_event ee = { .events = EPOLLIN };
441			int fd = accept4(h->listen_fd, NULL, NULL, SOCK_CLOEXEC | SOCK_NONBLOCK);
442			int idx = -1;
443	
444			if (fd < 0) {
445				if (errno != EAGAIN && errno != EINTR)
446					pss_log("accept4: %s", strerror(errno));
447				return;
448			}
449			for (int i = 0; i < MAX_CONNS; i++) {
450				if (h->conns[i].fd < 0) {
451					idx = i;
452					break;
453				}
454			}
455			if (idx < 0) {
456				pss_log("too many connections, refusing one");
457				close(fd);
458				continue;
459			}
460			ee.data.u32 = (uint32_t)idx;
461			if (epoll_ctl(h->epoll_fd, EPOLL_CTL_ADD, fd, &ee) != 0) {
462				pss_log("epoll_ctl ADD: %s", strerror(errno));
463				close(fd);
464				continue;
465			}
466			h->conns[idx] = (struct conn){ .fd = fd, .role = PSS_ROLE_NONE, .last_hb_ns = now };
467		}
468	}
