477	/* Stats record (1/min) doubles as the soak heartbeat line. 0 or -1. */
478	static int write_stats(struct hub *h, int64_t now)
479	{
480		struct pss_rec_stats r;
481	
482		memset(&r, 0, sizeof r);
483		r.mono_ns = now;
484		r.wall_ns = pss_wall_ns();
485		r.pir_edges = h->pir_edges;
486		r.mic_frames = h->mic_frames;
487		r.cam_bursts = h->cam_bursts;
488		r.cam_failures = h->cam_failures;
489		for (uint32_t role = PSS_ROLE_PIR; role <= PSS_ROLE_MIC; role++)
490			if (role_alive(h, role, now))
491				r.sensors_ok |= 1u << role;
492		if (store_append(&h->store, PSS_LOG_STATS, PSS_REC_STATS, &r, sizeof r) != 0 ||
493		    store_sync(&h->store, PSS_LOG_STATS) != 0)
494			return -1;
495		pss_log("hb: up=%" PRId64 "s pird=%s camd=%s micd=%s edges=%" PRIu64 " events=%" PRIu64
496			" bursts=%" PRIu64 " cam_fail=%" PRIu64 " mic_frames=%" PRIu64 " mic_onsets=%" PRIu64
497			" mic_zmax=%.1f mic_dbmax=%.1f",
498			(now - h->start_ns) / PSS_NS_PER_S, alive_str(h, PSS_ROLE_PIR, now),
499			alive_str(h, PSS_ROLE_CAM, now), alive_str(h, PSS_ROLE_MIC, now),
500			h->pir_edges, h->events_closed, h->cam_bursts, h->cam_failures, h->mic_frames, h->mic_onsets,
501			h->mic.z_max, h->mic.db_max);
502		h->mic.z_max = h->mic.db_max = 0;
503		return 0;
504	}
