543	static int epoll_add(struct hub *h, int fd, uint32_t tag)
544	{
545		struct epoll_event ee = { .events = EPOLLIN, .data.u32 = tag };
546	
547		if (epoll_ctl(h->epoll_fd, EPOLL_CTL_ADD, fd, &ee) != 0) {
548			pss_log("epoll_ctl ADD: %s", strerror(errno));
549			return -1;
