482	/* Closes every ENTRY left open by a power cut, keeping any images already committed. 0 or -1. */
483	static int close_interrupted(struct pss_store *s, const struct open_scan *scan)
484	{
485		for (size_t i = 0; i < scan->n; i++) {
486			const struct pss_rec_event_open *o = &scan->opens[i];
487			struct pss_rec_event e;
488	
489			memset(&e, 0, sizeof e);
490			e.event_id = o->event_id;
491			e.start_mono_ns = o->start_mono_ns;
492			e.end_mono_ns = o->start_mono_ns; /* end unknown */
493			e.start_wall_ns = o->start_wall_ns;
494			e.kind = o->kind;
495			e.flags = o->flags | PSS_EVF_INTERRUPTED;
496			if (clip_count_images(s->clips_dir_fd, o->event_id, &e.n_images) != 0)
497				return -1;
498			if (seglog_append(&s->events, PSS_REC_EVENT, &e, sizeof e) != 0)
499				return -1;
500			pss_log("store: event %" PRIu64 " was open when power was lost; closed as interrupted"
501				" (%" PRIu32 " images kept)", o->event_id, e.n_images);
502			s->recovered.interrupted++;
503		}
504		if (scan->n > 0 && seglog_sync(&s->events) != 0)
505			return -1;
506		return 0;
507	}
