276	static void test_sound_to_storage(void)
277	{
278		char root[256], data[300], run[300], fake[512], path[600], hub[512], camd[512], sock[300];
279		const char *bindir = getenv("PSS_BIN_DIR");
280		struct pss_msg m;
281		struct seen s = { 0 };
282		uint32_t st = 12345;
283		pid_t hp, cp;
284		int fd, i;
285	
286		t_mkdtemp(root);
287		snprintf(data, sizeof data, "%s/data", root);
288		snprintf(run, sizeof run, "%s/run", root);
289		snprintf(fake, sizeof fake, "%s/fake-rpicam-still.sh", getenv("PSS_TEST_DIR"));
290		CHECK(chmod(fake, 0755) == 0);
291		setenv("PSS_DATA_DIR", data, 1);
292		setenv("PSS_RUN_DIR", run, 1);
293		setenv("PSS_RPICAM", fake, 1);
294		unsetenv("FAKE_RPICAM_FAIL");
295		snprintf(hub, sizeof hub, "%s/hub", bindir);
296		snprintf(camd, sizeof camd, "%s/camd", bindir);
297	
298		hp = spawn((char *[]){ hub, "--quiet-ms=300", "--burst-frames=3", "--burst-interval-ms=20",
299				       "--warmup-frames=250", "--onset-z=6", "--onset-db=10", NULL });
300		CHECK(hp > 0);
301		CHECK(ipc_sock_path(sock, sizeof sock) == 0);
302		fd = connect_retry(sock);
303		CHECK(fd >= 0);
304		cp = spawn((char *[]){ camd, NULL });
305		CHECK(cp > 0);
306	
307		/* Act as micd. */
308		pss_msg_init(&m, PSS_MSG_HELLO);
309		m.u.hello.role = PSS_ROLE_MIC;
310		m.u.hello.pid = (uint32_t)getpid();
311		CHECK(ipc_send(fd, &m) == 0);
312		sleep_ms(1000); /* let camd connect */
313	
314		/* 10 s of a steady fan, then the fan slowly turned up ~9.5 dB over 30 s. */
315		for (i = 0; i < 500; i++)
316			send_fan(fd, &st, 0.02);
317		for (i = 0; i < 1500; i++)
318			send_fan(fd, &st, 0.02 * (1.0 + 2.0 * i / 1500.0));
319		sleep_ms(1500); /* past a 1 s tick, so any event would have closed */
320		CHECK(count_events(data, &s) == 0);
321	
322		/* A clap: broadband jump (big flux, ~+18 dB), then the fan again. */
323		send_mic_frame(fd, 0.5, 5.0);
324		for (i = 0; i < 100; i++)
325			send_fan(fd, &st, 0.06);
326		for (i = 0; i < 100 && count_events(data, &s) == 0; i++)
327			sleep_ms(100);
328		CHECK(s.events == 1);
329		CHECK(s.last.kind == PSS_EV_SOUND_ONLY);
330		CHECK(s.last.pir_edges == 0);
331		CHECK(s.last.n_images == 0);	/* sound alone takes no images */
332		CHECK(!(s.last.flags & PSS_EVF_NO_IMAGES));
333		CHECK(!(s.last.flags & PSS_EVF_AUDIO_OFFLINE));
334		CHECK(s.opens == 0);
335		snprintf(path, sizeof path, "%s/clips/%" PRIu64 ".dir", data, s.last.event_id);
336		CHECK(count_entries(path, ".jpg") == -1);	/* no clip directory at all */
337		snprintf(path, sizeof path, "%s/clips", data);
338		CHECK(count_entries(path, ".tmp") == 0);
339	
340		CHECK(stop(cp) == 0);
341		CHECK(stop(hp) == 0);
342		close(fd);
343		CHECK(count_events(data, &s) == 1); /* nothing left open at shutdown */
344		t_rm_rf(root);
345	}
346	
347	static int connect_as(const char *sock, uint32_t role)
348	{
349		struct pss_msg m;
350		int fd = connect_retry(sock);
351	
352		CHECK(fd >= 0);
353		pss_msg_init(&m, PSS_MSG_HELLO);
354		m.u.hello.role = role;
355		m.u.hello.pid = (uint32_t)getpid();
356		CHECK(ipc_send(fd, &m) == 0);
357		return fd;
358	}
359	
360	/* Waits (up to 10 s) until the events log holds n complete events. */
361	static void wait_events(const char *data, int n, struct seen *s)
362	{
363		for (int i = 0; i < 100 && count_events(data, s) < n; i++)
364			sleep_ms(100);
365		CHECK(s->events == n);
366	}
367	
368	/* Checks the newest event is a confirmed ENTRY with 3 images on disk. */
369	static void check_entry_with_images(const char *data, const struct seen *s)
370	{
371		char path[600];
372	
373		CHECK(s->last.kind == PSS_EV_ENTRY);
374		CHECK(s->last.n_images == 3);
375		CHECK(!(s->last.flags & PSS_EVF_NO_IMAGES));
376		CHECK(s->last_open.event_id == s->last.event_id);	/* made durable when confirmed */
377		CHECK(s->last_open.kind == PSS_EV_ENTRY);
378		snprintf(path, sizeof path, "%s/clips/%" PRIu64 ".dir", data, s->last.event_id);
379		CHECK(count_entries(path, ".jpg") == 3);
380	}
381	
382	/*
383	 * One hub+camd lifetime with the test acting as both pird and micd.
384	 * T_co is 500 ms here. cam_fail: run only case (a), with the camera failing.
385	 */
386	static void entry_session(const char *data, int cam_fail)
387	{
388		char hub[512], camd[512], sock[300], path[600];
389		const char *bindir = getenv("PSS_BIN_DIR");
390		struct seen s = { 0 };
391		uint32_t st = 777;
392		pid_t hp, cp;
393		int pfd, mfd, n0, i;
394	
395		snprintf(hub, sizeof hub, "%s/hub", bindir);
396		snprintf(camd, sizeof camd, "%s/camd", bindir);
397		if (cam_fail)
398			setenv("FAKE_RPICAM_FAIL", "1", 1);
399		else
400			unsetenv("FAKE_RPICAM_FAIL");
401		n0 = access(data, F_OK) == 0 ? count_events(data, &s) : 0;
402	
403		hp = spawn((char *[]){ hub, "--quiet-ms=300", "--burst-frames=3", "--burst-interval-ms=20",
404				       "--warmup-frames=50", "--t-co-ms=500", NULL });
405		CHECK(hp > 0);
406		CHECK(ipc_sock_path(sock, sizeof sock) == 0);
407		pfd = connect_as(sock, PSS_ROLE_PIR);
408		mfd = connect_as(sock, PSS_ROLE_MIC);
409		cp = spawn((char *[]){ camd, NULL });
410		CHECK(cp > 0);
411		sleep_ms(1000);	/* let camd connect */
412		for (i = 0; i < 100; i++)	/* learn the room background */
413			send_fan(mfd, &st, 0.02);
414	
415		/* (a) Door: latch sound first, then the person walks into view. */
416		send_mic_frame(mfd, 0.5, 5.0);
417		sleep_ms(100);
418		send_edge(pfd, 1);
419		sleep_ms(50);
420		send_edge(pfd, 0);
421		wait_events(data, n0 + 1, &s);
422		CHECK(s.last.pir_edges == 1);
423		CHECK(!(s.last.flags & PSS_EVF_AUDIO_OFFLINE));
424		if (cam_fail) {
425			CHECK(s.last.kind == PSS_EV_ENTRY);
426			CHECK(s.last.flags & PSS_EVF_NO_IMAGES);
427			CHECK(s.last.n_images == 0);
428			goto done;
429		}
430		check_entry_with_images(data, &s);
431	
432		/* (b) Motion first, then the sound 200 ms later. */
433		send_edge(pfd, 1);
434		sleep_ms(200);
435		send_mic_frame(mfd, 0.5, 5.0);
436		sleep_ms(50);
437		send_edge(pfd, 0);
438		wait_events(data, n0 + 2, &s);
439		check_entry_with_images(data, &s);
440	
441		/* (c) Motion and sound 1 s apart (> T_co): no ENTRY, no images. The PIR
442		 * stays high in between so both land in one event. */
443		send_edge(pfd, 1);
444		sleep_ms(1000);
445		send_mic_frame(mfd, 0.5, 5.0);
446		sleep_ms(50);
447		send_edge(pfd, 0);
448		wait_events(data, n0 + 3, &s);
449		CHECK(s.last.kind == PSS_EV_MOTION_ONLY);
450		CHECK(s.last.n_images == 0);
451		CHECK(s.opens == 2);	/* only (a) and (b) were confirmed */
452		snprintf(path, sizeof path, "%s/clips/%" PRIu64 ".dir", data, s.last.event_id);
453		CHECK(count_entries(path, ".jpg") == -1);
454	done:
455		snprintf(path, sizeof path, "%s/clips", data);
456		CHECK(count_entries(path, ".tmp") == 0);
457		CHECK(stop(cp) == 0);
458		CHECK(stop(hp) == 0);
459		close(pfd);
460		close(mfd);
461		unsetenv("FAKE_RPICAM_FAIL");
462	}
463	
464	static void test_entry_to_storage(void)
465	{
466		char root[256], data[300], run[300], fake[512];
467	
468		t_mkdtemp(root);
469		snprintf(data, sizeof data, "%s/data", root);
470		snprintf(run, sizeof run, "%s/run", root);
471		snprintf(fake, sizeof fake, "%s/fake-rpicam-still.sh", getenv("PSS_TEST_DIR"));
472		CHECK(chmod(fake, 0755) == 0);
473		setenv("PSS_DATA_DIR", data, 1);
474		setenv("PSS_RUN_DIR", run, 1);
475		setenv("PSS_RPICAM", fake, 1);
476	
477		entry_session(data, 0);	/* (a) sound->motion, (b) motion->sound, (c) too far apart */
478		entry_session(data, 1);	/* (d) camera fails: ENTRY kept, flagged no-images */
479		t_rm_rf(root);
480	}
481	
482	int main(void)
483	{
484		if (getenv("PSS_BIN_DIR") == NULL || getenv("PSS_TEST_DIR") == NULL) {
485			fprintf(stderr, "run via `make test` (needs PSS_BIN_DIR and PSS_TEST_DIR)\n");
486			return 2;
487		}
488		T_RUN(test_pir_to_storage);
489		T_RUN(test_sound_to_storage);
490		T_RUN(test_entry_to_storage);
491		T_END();
492	}
