43	
44		fusion_init(&f, 3 * S);
45		CHECK(fusion_rise(&f, 10 * S, NULL) == 0);
46		CHECK(fusion_onset(&f, 13 * S, NULL) == 1);
47		fusion_init(&f, 3 * S);
48		CHECK(fusion_onset(&f, 10 * S, NULL) == 0);
49		CHECK(fusion_rise(&f, 13 * S, NULL) == 1);
50		fusion_init(&f, 3 * S);
51		CHECK(fusion_onset(&f, 10 * S, NULL) == 0);
52		CHECK(fusion_rise(&f, 13 * S + 1, NULL) == 0);
53	}
